def solve(inputs: dict) -> float:
    A = inputs.get('matrix', inputs.get('M'))
    e = inputs.get('power', inputs.get('exponent', inputs.get('n')))
    mod = inputs.get('modulus', inputs.get('mod', inputs.get('MOD')))
    if A is None or e is None or mod is None:
        raise KeyError('Expected matrix/M, power/exponent/n, and modulus/mod/MOD')
    A = [[int(v) % int(mod) for v in row] for row in A]
    mod, e, size = int(mod), int(e), len(A)
    if any(len(row) != size for row in A):
        raise ValueError('Matrix must be square')
    R = [[int(i == j) for j in range(size)] for i in range(size)]
    def mul(X, Y):
        return [[sum(X[i][k] * Y[k][j] for k in range(size)) % mod
                 for j in range(size)] for i in range(size)]
    while e:
        if e & 1:
            R = mul(R, A)
        A = mul(A, A)
        e >>= 1
    return sum(map(sum, R))

